14	import { editBookingSchema } from './booking-form-schema';
15	import type { BookingFormContext, EditBookingFormValues } from './booking-form-schema';
16	import { errorMessage } from './error-message';
17	import { isoToUtcInput, utcInputToIso } from './utc-date-time';
18	
19	const toFormValues = (booking: BookingDto): EditBookingFormValues => ({
20	  title: booking.title,
21	  startsAt: isoToUtcInput(booking.startsAt),
22	  endsAt: isoToUtcInput(booking.endsAt),
23	});
24	
25	const changedFields = (shown: EditBookingFormValues, entered: EditBookingFormValues): UpdateBookingDto => ({
26	  ...(entered.title !== shown.title && { title: entered.title }),
27	  ...(entered.startsAt !== shown.startsAt && { startsAt: utcInputToIso(entered.startsAt) }),
28	  ...(entered.endsAt !== shown.endsAt && { endsAt: utcInputToIso(entered.endsAt) }),
29	});
30	
31	type EditBookingDialogProps = {
32	  booking: BookingDto;
33	  onClose: () => void;
34	  onSaved: () => void;
35	};
36	
37	export function EditBookingDialog({ booking, onClose, onSaved }: EditBookingDialogProps) {
38	  const titleId = useId();
39	  const shown = toFormValues(booking);
40	  const form = useForm<EditBookingFormValues, BookingFormContext>({
41	    defaultValues: shown,
42	    resolver: yupResolver(editBookingSchema),
43	    context: { storedSpan: { startsAt: shown.startsAt, endsAt: shown.endsAt } },
44	  });
45	  const [saveError, setSaveError] = useState<string | null>(null);
46	
47	  const save = async (entered: EditBookingFormValues) => {
48	    const changes = changedFields(shown, entered);
49	    if (Object.keys(changes).length === 0) {
50	      onClose();
51	      return;
52	    }
53	    setSaveError(null);
54	    try {
55	      await updateBooking(booking.id, changes);
56	    } catch (error) {
57	      setSaveError(errorMessage(error));
58	      return;
59	    }
60	    onSaved();
61	  };
62	
63	  return (
64	    <Dialog open onClose={onClose} aria-labelledby={titleId} fullWidth maxWidth="xs">
65	      <FormProvider {...form}>
66	        <form noValidate onSubmit={form.handleSubmit(save)}>
67	          <DialogTitle id={titleId}>Edit booking</DialogTitle>
68	          <DialogContent>
69	            <Stack spacing={2} sx={{ pt: 1 }}>
70	              {saveError && <Alert severity="error">{saveError}</Alert>}
71	              <BookingScheduleFields />
72	            </Stack>
73	          </DialogContent>
74	          <DialogActions>
75	            <Button onClick={onClose}>Cancel</Button>
76	            <Button type="submit" variant="contained" disabled={form.formState.isSubmitting}>
77	              Save
78	            </Button>
79	          </DialogActions>
80	        </form>
81	      </FormProvider>
82	    </Dialog>
83	  );
84	}
