1	import { Injectable } from '@nestjs/common';
2	import { InjectRepository } from '@nestjs/typeorm';
3	import { BookingEntity, BOOKINGS_SPAN_CONSTRAINT } from '@roombook/backend-common';
4	import {
5	  BookingDto,
6	  ConfirmationStatusEnum,
7	  ListBookingsQueryDto,
8	  PagedBookingsDto,
9	  RecordConfirmationResultDto,
10	} from '@roombook/contract';
11	import { DataSource, LessThanOrEqual, Not, QueryFailedError, Repository } from 'typeorm';
12	import { BookingChangesDto, mergeBookingChanges, rejectInvalidSpan } from './booking-input';
13	
14	type ConstraintError = Error & { constraint?: string };
15	
16	export const toBookingDto = (entity: BookingEntity): BookingDto => ({
17	  id: entity.id,
18	  roomId: entity.roomId,
19	  title: entity.title,
20	  organizerEmail: entity.organizerEmail,
21	  startsAt: entity.startsAt.toISOString(),
22	  endsAt: entity.endsAt.toISOString(),
23	  confirmationStatus: entity.confirmationStatus,
24	  confirmationAttempts: entity.confirmationAttempts,
25	  createdAt: entity.createdAt.toISOString(),
26	  updatedAt: entity.updatedAt.toISOString(),
27	});
28	
29	export const violatedConstraint = (error: unknown): string | undefined =>
30	  error instanceof QueryFailedError ? (error.driverError as ConstraintError).constraint : undefined;
31	
32	export const rethrowSpanViolation = (error: unknown): never => {
33	  if (violatedConstraint(error) === BOOKINGS_SPAN_CONSTRAINT) {
34	    return rejectInvalidSpan();
35	  }
36	  throw error;
37	};
38	
39	@Injectable()
40	export class BookingRepository {
41	  constructor(
42	    @InjectRepository(BookingEntity) private readonly bookings: Repository<BookingEntity>,
43	    private readonly dataSource: DataSource,
44	  ) {}
45	
46	  async findPage(query: ListBookingsQueryDto): Promise<PagedBookingsDto> {
47	    const where = query.roomId ? { roomId: query.roomId } : {};
48	    const skip = (query.page - 1) * query.limit;
49	    // Postgres refuses an OFFSET beyond bigint; such a page is past the end.
50	    if (!Number.isSafeInteger(skip)) {
51	      return { items: [], total: await this.bookings.count({ where }), page: query.page, limit: query.limit };
52	    }
53	    const [entities, total] = await this.bookings.findAndCount({
54	      where,
55	      order: { startsAt: 'ASC', id: 'ASC' },
56	      skip,
57	      take: query.limit,
58	    });
59	    return { items: entities.map(toBookingDto), total, page: query.page, limit: query.limit };
60	  }
61	
62	  async findById(id: string): Promise<BookingDto | null> {
63	    const entity = await this.bookings.findOneBy({ id });
64	    return entity ? toBookingDto(entity) : null;
65	  }
66	
67	  async deleteById(id: string): Promise<boolean> {
68	    const result = await this.bookings.delete({ id });
69	    return result.affected === 1;
70	  }
71	
72	  update(id: string, changes: BookingChangesDto): Promise<BookingDto | null> {
73	    return this.dataSource
74	      .transaction(async (manager) => {
75	        const stored = await manager.findOne(BookingEntity, { where: { id }, lock: { mode: 'pessimistic_write' } });
76	        if (!stored) {
77	          return null;
78	        }
79	        const changed = mergeBookingChanges(stored, changes);
80	        if (Object.keys(changed).length === 0) {
81	          return toBookingDto(stored);
82	        }
83	        await manager.update(BookingEntity, { id }, changed);
84	        return toBookingDto(await manager.findOneByOrFail(BookingEntity, { id }));
85	      })
86	      .catch(rethrowSpanViolation);
87	  }
88	
89	  async recordConfirmation(result: RecordConfirmationResultDto): Promise<BookingDto | null> {
90	    await this.bookings.update(
91	      {
92	        id: result.bookingId,
93	        confirmationStatus: Not(ConfirmationStatusEnum.SENT),
94	        confirmationAttempts: LessThanOrEqual(result.attempts),
95	      },
96	      { confirmationStatus: result.status, confirmationAttempts: result.attempts },
97	    );
98	    return this.findById(result.bookingId);
99	  }
100	}
