1	import { useCallback, useRef } from 'react';
2	import { v4 as uuidv4 } from 'uuid';
3	import { ErrorCodeEnum } from '@roombook/contract';
4	import { ApiError } from '../../services/api-error';
5	
6	type IssuedKey = {
7	  key: string;
8	  payload: string;
9	};
10	
11	const FIRST_SERVER_ERROR_STATUS = 500;
12	
13	const isFinalAnswer = (error: unknown): boolean =>
14	  error instanceof ApiError &&
15	  error.statusCode < FIRST_SERVER_ERROR_STATUS &&
16	  error.errorCode !== ErrorCodeEnum.IDEMPOTENCY_IN_PROGRESS;
17	
18	export function useIdempotencyKey() {
19	  const issued = useRef<IssuedKey | null>(null);
20	
21	  const keyFor = useCallback((payload: object): string => {
22	    const serialized = JSON.stringify(payload);
23	    if (issued.current?.payload !== serialized) issued.current = { key: uuidv4(), payload: serialized };
24	    return issued.current.key;
25	  }, []);
26	
27	  const settle = useCallback((error?: unknown): void => {
28	    if (error === undefined || isFinalAnswer(error)) issued.current = null;
29	  }, []);
30	
31	  return { keyFor, settle };
32	}
33

1	import type { ErrorResponseDto } from '@roombook/contract';
2	
3	export class ApiError extends Error {
4	  readonly statusCode: number;
5	  readonly errorCode: string;
6	
7	  constructor({ statusCode, errorCode, message }: ErrorResponseDto) {
8	    super(message);
9	    this.name = 'ApiError';
10	    this.statusCode = statusCode;
11	    this.errorCode = errorCode;
12	  }
13	}
